-- 厂商适配档案：把「各家 OpenAI 兼容协议的差异」从代码搬到表里。
--
-- 此前这些差异写在 Go 的注册表里，加一家要改代码、发版；
-- 落表后由管理员在后台维护，代码只保留「档案怎么解读」的逻辑。
-- 首次迁移灌入已知厂商作为默认值，之后以表内数据为准。

CREATE TABLE IF NOT EXISTS vendor_profiles (
  id          bigserial PRIMARY KEY,
  code        varchar(64)  NOT NULL,
  name        varchar(128) NOT NULL DEFAULT '',
  group_name  varchar(32)  NOT NULL DEFAULT '',
  match_hosts text         NOT NULL DEFAULT '',
  enabled     boolean      NOT NULL DEFAULT true,
  sort        integer      NOT NULL DEFAULT 0,
  config      jsonb        NOT NULL DEFAULT '{}'::jsonb,
  builtin     boolean      NOT NULL DEFAULT false,
  created_at  timestamptz  NOT NULL DEFAULT now(),
  updated_at  timestamptz  NOT NULL DEFAULT now()
);

COMMENT ON TABLE vendor_profiles IS '厂商适配档案：按上游地址识别厂商，决定端点、鉴权、字段命名与错误解析';
COMMENT ON COLUMN vendor_profiles.code IS '档案唯一代码，与 config.id 一致';
COMMENT ON COLUMN vendor_profiles.match_hosts IS '按上游地址识别用的主机关键词，逗号分隔；也支持端口号（如 11434）';
COMMENT ON COLUMN vendor_profiles.config IS '档案详情 JSON，字段见 internal/pkg/gateway/vendor.Vendor';
COMMENT ON COLUMN vendor_profiles.builtin IS '内置档案：随迁移灌入的默认值，界面上提示谨慎修改';

CREATE UNIQUE INDEX IF NOT EXISTS uk_vendor_profiles_code ON vendor_profiles (code);

