-- 迁移灌入的都标记为内置：界面据此提示，删除后重新迁移可恢复。
UPDATE vendor_profiles SET builtin = true WHERE builtin = false;

-- 种子写死了 id，必须把序列推到最大值之后：
-- 否则新建档案会从 1 开始分配，直接撞主键（报成"代码已存在"，很难排查）。
SELECT setval(pg_get_serial_sequence('vendor_profiles', 'id'), GREATEST((SELECT COALESCE(MAX(id), 0) FROM vendor_profiles), 1));
